import * as React from 'react';
import cx from 'clsx';

import { delay } from '../coreUtils/async';
import { Events, EventObserver, EventSource, PropertyChange } from '../coreUtils/events';
import {
    useEventStore, useObservedProperty, useSyncStoreWithComparator,
} from '../coreUtils/hooks';
import type { Translation } from '../coreUtils/i18n';

import { CanvasPointerUpEvent, CanvasKeyboardEvent, useCanvas } from '../diagram/canvasApi';
import { Element, Link, LinkVertex } from '../diagram/elements';
import { Size, Vector } from '../diagram/geometry';
import { DiagramModel } from '../diagram/model';
import { CanvasPlaceAt } from '../diagram/placeLayer';
import { type MutableRenderingState, useLayerDebouncedStore } from '../diagram/renderingState';
import { SharedCanvasState } from '../diagram/sharedCanvasState';
import { Spinner, SpinnerProps } from '../diagram/spinner';

import { Dialog, DialogProps, DialogStyleProps, DialogTarget } from '../widgets/dialog';
import { getParentDockMargin } from '../widgets/utility/viewportDock';

/** @hidden */
export interface OverlayControllerProps {
    readonly model: DiagramModel;
    readonly view: SharedCanvasState;
    readonly translation: Translation;
    readonly dialogSettingsProvider: DialogSettingsProvider;
}

/**
 * Event data for {@link OverlayController} events.
 *
 * @see {@link OverlayController}
 */
export interface OverlayControllerEvents {
    /**
     * Triggered on {@link OverlayController.openedDialog} property change.
     */
    changeOpenedDialog: PropertyChange<OverlayController, OverlayDialog | undefined>;
}

/**
 * Describes a dialog opened as an overlay for the canvas.
 *
 * @see {@link OverlayController.openedDialog}
 * @see {@link OverlayController.showDialog}
 */
export interface OverlayDialog {
    /**
     * Dialog target (anchor).
     */
    readonly target?: Element | Link;
    /**
     * Well-known dialog type to check if a specific dialog is currently open.
     */
    readonly knownType: OverlayDialogType | undefined;
    /**
     * Whether the diagram should not change selection
     * while the dialog is opened.
     */
    readonly holdSelection: boolean;
    /**
     * Handler which will be called when dialog is closed.
     */
    readonly onClose: (() => void) | undefined;
}

/**
 * Nominal (branded) type for known overlay dialog type.
 *
 * @see {@link OverlayDialog.knownType}
 */
export type OverlayDialogType = string & { overlayDialogTypeBrand: void };

/**
 * Provides defaults and persists changes to {@link OverlayDialog overlay dialog} properties.
 *
 * @category Core
 */
export interface DialogSettingsProvider {
    /**
     * Provides size defaults for an opened dialog: `defaultSize`, `minSize` and `maxSize`.
     *
     * **Note**: returned defaults will override corresponding values passed as `style`
     * to {@link OverlayController.showDialog}.
     */
    getDialogSize(
        dialog: OverlayDialog
    ): Pick<DialogStyleProps, 'defaultSize' | 'minSize' | 'maxSize'> | undefined;
    /**
     * Stores the new dialog size after it has been resized by the user.
     */
    persistDialogSize(dialog: OverlayDialog, size: Size): void;
}

/**
 * Controls UI overlays for the canvases, including dialogs and tasks.
 *
 * @category Core
 */
export class OverlayController {
    private readonly source = new EventSource<OverlayControllerEvents>();
    readonly events: Events<OverlayControllerEvents> = this.source;

    private readonly internalSource = new EventSource<OverlayControllerInternalEvents>();

    private readonly model: DiagramModel;
    private readonly view: SharedCanvasState;
    private readonly translation: Translation;
    private readonly dialogSettingsProvider: DialogSettingsProvider;

    private _openedDialog: OverlayDialog | undefined;
    private _tasks = new Set<ExtendedOverlayTask>();
    private _taskError: { error: unknown } | undefined;

    /** @hidden */
    constructor(props: OverlayControllerProps) {
        const {model, view, translation, dialogSettingsProvider} = props;
        this.model = model;
        this.view = view;
        this.translation = translation;
        this.dialogSettingsProvider = dialogSettingsProvider;

        withInternalApi(this)[OverlayInternalApi] = {
            events: this.internalSource,
            overlays: new Set<OverlayReader>(),
            dialog: null,
            spinner: null,
            onCanvasPointerUp: this.onAnyCanvasPointerUp,
            onCanvasKeydown: this.onAnyCanvasKeydown,
        };

        const listener = new EventObserver();
        listener.listen(this.model.events, 'changeSelection', () => {
            const target = this.model.selection.length === 1 ? this.model.selection[0] : undefined;
            if (this.openedDialog && this.openedDialog.target !== target) {
                this.hideDialog();
            }
        });
        listener.listen(this.model.events, 'discardGraph', () => {
            if (this.openedDialog && this.openedDialog.target) {
                this.hideDialog();
            }
        });
    }

    /**
     * Currently open dialog.
     *
     * Returns `undefined` if no dialog is opened.
     */
    get openedDialog(): OverlayDialog | undefined {
        return this._openedDialog;
    }

    private onAnyCanvasPointerUp = (event: CanvasPointerUpEvent): void => {
        const {source: canvas, sourceEvent, target, triggerAsClick} = event;

        if (sourceEvent.ctrlKey || sourceEvent.shiftKey || sourceEvent.metaKey) {
            return;
        }
        if (this.openedDialog && this.openedDialog.holdSelection) {
            return;
        }

        if (target instanceof Element) {
            this.model.setSelection([target]);
            target.focus();
        } else if (target instanceof Link) {
            this.model.setSelection([target]);
            canvas.focus();
        } else if (target instanceof LinkVertex) {
            this.model.setSelection([target.link]);
            canvas.focus();
        } else if (!target && triggerAsClick) {
            this.model.setSelection([]);
            this.hideDialog();
            canvas.focus();
        }
    };

    private onAnyCanvasKeydown = (event: CanvasKeyboardEvent): void => {
        const {source, sourceEvent} = event;
        const renderingState = source.renderingState as MutableRenderingState;
        renderingState.triggerHotkey(sourceEvent);
    };

    /**
     * Starts a new foreground task which blocks canvas interaction and
     * displays a loading indicator until the task has ended.
     *
     * If multiple tasks are started at any given time, an indicator will be shown
     * while at least one of them is still active.
     */
    startTask(params: {
        /**
         * Task title to display.
         */
        title?: string;
        /**
         * Delay in milliseconds before displaying loading indicator to avoid showing it
         * in case the task ends quickly.
         *
         * @default 0
         */
        delay?: number;
    } = {}): OverlayTask {
        const {title, delay: delayMs = 0} = params;

        if (this._tasks.size === 0 && this._taskError) {
            // Clear the error
            this._taskError = undefined;
        }

        const delayed = delayMs > 0 && this._tasks.size === 0;
        const createdTask: ExtendedOverlayTask = {
            title,
            setError: (error: unknown) => {
                this._taskError = {error};
            },
            end: () => {
                this._tasks.delete(createdTask);
                this.updateTaskSpinner();
            },
            [OverlayTaskActive]: !delayed,
        };
        this._tasks.add(createdTask);
        this.updateTaskSpinner();

        if (delayed) {
            void delay(delayMs).then(() => {
                if (this._tasks.has(createdTask)) {
                    // Activate all tasks if any activates
                    for (const task of this._tasks) {
                        task[OverlayTaskActive] = true;
                    }
                    this.updateTaskSpinner();
                }
            });
        }

        return createdTask;
    }

    /**
     * Creates a task via {@link startTask} for the operation defined by a `Promise`.
     *
     * @see {@link startTask}
     */
    showSpinnerWhile(operation: Promise<unknown>): void {
        const {translation: t} = this;
        const task = this.startTask();
        void (async () => {
            try {
                await operation;
            } catch (err) {
                console.error(err);
                task.setError(new Error(
                    t.text('overlay_controller.unknown_error'),
                    {cause: err}
                ));
            } finally {
                task.end();
            }
        })();
    }

    private updateTaskSpinner(): void {
        const {translation: t} = this;
        if (this._taskError) {
            const statusText = getErrorMessage(this._taskError.error);
            this.setSpinner({statusText, errorOccurred: true});
        } else {
            let hasActiveTask = false;
            let title: string | undefined;
            for (const task of this._tasks) {
                if (task[OverlayTaskActive]) {
                    hasActiveTask = true;
                }

                if (task.title) {
                    if (title === undefined) {
                        title = task.title;
                    } else {
                        title = t.text('overlay_controller.multiple_tasks_in_progress');
                        break;
                    }
                }
            }

            if (hasActiveTask) {
                this.setSpinner({statusText: title});
            } else {
                this.setSpinner(undefined);
            }
        }
    }

    private setSpinner(props: SpinnerProps | undefined) {
        const internalApi = withInternalApi(this)[OverlayInternalApi];
        const spinner = props ? <LoadingWidget spinnerProps={props} /> : null;
        const previous = internalApi.spinner;
        internalApi.spinner = spinner;
        this.internalSource.trigger('changeSpinner', {previous, source: this});
    }

    /**
     * Shows on-canvas dialog anchored to the target element or link.
     *
     * @see {@link hideDialog}
     */
    showDialog(params: {
        /**
         * Element or link to anchor dialog to.
         */
        target?: Element | Link;
        /**
         * Dialog style, placement and sizing options.
         */
        style: DialogStyleProps;
        /**
         * Dialog content.
         */
        content: React.ReactElement<any>;
        /**
         * Well-known dialog type to check later if a specific dialog is currently open.
         */
        dialogType?: OverlayDialogType;
        /**
         * Whether to prevent selection changes while dialog is open.
         *
         * @default false
         */
        holdSelection?: boolean;
        /**
         * Callback which is called when dialog is closed for any reason
         * (e.g. when another dialog is opened).
         */
        onClose?: () => void;
    }): void {
        const {target, style, dialogType, content, holdSelection = false, onClose} = params;
        if (this._openedDialog && this._openedDialog.target !== target) {
            this.hideDialog();
        }

        const openedDialog: OverlayDialog = {
            target,
            knownType: dialogType,
            holdSelection,
            onClose,
        };

        const canvas = this.view.findAnyCanvas();
        const breakpoint = readOverlayProperty(
            withInternalApi(this)[OverlayInternalApi].overlays,
            reader => reader.getDialogViewportBreakpoint()
        );
        const isSmallViewport = Boolean(
            canvas && breakpoint !== undefined && canvas.metrics.pane.clientWidth <= breakpoint
        );

        let styleWithDefaults = style;
        const sizeOverrides = this.dialogSettingsProvider.getDialogSize(openedDialog);
        if (sizeOverrides) {
            styleWithDefaults = {
                ...style,
                defaultSize: sizeOverrides.defaultSize ?? style.defaultSize,
                minSize: sizeOverrides.minSize ?? style.minSize,
                maxSize: sizeOverrides.maxSize ?? style.maxSize,
            };
        }

        const onResize: DialogProps['onResize'] = size => {
            this.dialogSettingsProvider.persistDialogSize(openedDialog, size);
        };
        const onHide = () => this.hideDialog();
        const closeTitle = this.translation.text('overlay_controller.dialog_close.title');
        if (target && !isSmallViewport) {
            this.setDialog(
                openedDialog,
                <CanvasPlaceAt layer='overElements'>
                    <Dialog {...styleWithDefaults}
                        target={
                            target instanceof Element ? DialogTarget.forElement(target) :
                            target instanceof Link ? DialogTarget.forLink(target) :
                            target
                        }
                        onResize={onResize}
                        onHide={onHide}
                        closeTitle={closeTitle}>
                        {content}
                    </Dialog>
                </CanvasPlaceAt>
            );
        } else {
            this.setDialog(
                openedDialog,
                <ViewportDialog {...styleWithDefaults}
                    mode={isSmallViewport ? 'fillViewport' : 'centered'}
                    onResize={onResize}
                    onHide={onHide}
                    closeTitle={closeTitle}>
                    {content}
                </ViewportDialog>
            );
        }
    }

    /**
     * Closes currently open dialog if any is active.
     *
     * @see {@link showDialog}
     */
    hideDialog() {
        if (this._openedDialog) {
            const previous = this._openedDialog;
            previous.onClose?.();
            this.setDialog(undefined, null);
        }
    }

    private setDialog(
        openedDialog: OverlayDialog | undefined,
        dialog: React.ReactElement | null
    ): void {
        const internalApi = withInternalApi(this)[OverlayInternalApi];
        const previousDialog = this._openedDialog;
        const previous = internalApi.dialog;
        this._openedDialog = openedDialog;
        internalApi.dialog = dialog;
        this.internalSource.trigger('changeDialog', {previous, source: this});
        this.source.trigger('changeOpenedDialog', {
            source: this,
            previous: previousDialog,
        });
    }
}

/**
 * Represents a foreground canvas task.
 */
export interface OverlayTask {
    /**
     * Task title to display.
     */
    readonly title: string | undefined;
    /**
     * Marks the task as failed with the specified error.
     *
     * If set, the error will be displayed until another task
     * will be started later.
     *
     * This method can be called multiple times and will not
     * complete the task (i.e. {@link end end()} method call is required).
     */
    setError(error: unknown): void;
    /**
     * Completes the task and removes its representation from the overlay.
     *
     * If the task is marked with error via {@link setError setError()}, that error
     * will be kept displaying until another task is started later.
     */
    end(): void;
}

const OverlayTaskActive: unique symbol = Symbol('OverlayTask.active');

interface ExtendedOverlayTask extends OverlayTask {
    [OverlayTaskActive]: boolean;
}

const OverlayInternalApi: unique symbol = Symbol('OverlayController.internalApi');

interface OverlayWithInternalApi {
    [OverlayInternalApi]: OverlayControllerInternalApi;
}

interface OverlayControllerInternalApi {
    readonly events: Events<OverlayControllerInternalEvents>;
    readonly overlays: Set<OverlayReader>;
    readonly onCanvasPointerUp: (event: CanvasPointerUpEvent) => void;
    readonly onCanvasKeydown: (event: CanvasKeyboardEvent) => void;
    dialog: React.ReactElement<any> | null;
    spinner: React.ReactElement<any> | null;
}

interface OverlayControllerInternalEvents {
    changeDialog: PropertyChange<OverlayController, React.ReactElement | null>;
    changeSpinner: PropertyChange<OverlayController, React.ReactElement | null>;
}

interface OverlayReader {
    getDialogViewportBreakpoint(): number | undefined;
}

function withInternalApi(controller: OverlayController): OverlayWithInternalApi {
    return controller as Partial<OverlayWithInternalApi> as OverlayWithInternalApi;
}

function readOverlayProperty<T>(
    readers: Iterable<OverlayReader>,
    getProperty: (reader: OverlayReader) => T | undefined
): T | undefined {
    for (const reader of readers) {
        const value = getProperty(reader);
        if (value !== undefined) {
            return value;
        }
    }
    return undefined;
}

export function OverlaySupport(props: {
    overlay: OverlayController;
}) {
    const {overlay} = props;
    const {canvas} = useCanvas();

    const internalApi = withInternalApi(overlay)[OverlayInternalApi];
    const {overlays, onCanvasPointerUp, onCanvasKeydown} = internalApi;

    const ref = React.useRef<HTMLDivElement>(null);
    React.useLayoutEffect(() => {
        const overlay = ref.current;
        if (overlay) {
            const reader: OverlayReader = {
                getDialogViewportBreakpoint: () => {
                    const style = getComputedStyle(overlay);
                    // Use parseFloat to ignore trailing "px" unit at the end
                    return style.maxWidth ? parseFloat(style.maxWidth) : undefined;
                },
            };
            overlays.add(reader);
            return () => {
                overlays.delete(reader);
            };
        }
    }, [overlays]);

    React.useEffect(() => {
        const listener = new EventObserver();
        listener.listen(canvas.events, 'pointerUp', onCanvasPointerUp);
        listener.listen(canvas.events, 'keydown', onCanvasKeydown);
        return () => listener.stopListening();
    }, [onCanvasPointerUp, onCanvasKeydown]);

    const dialog = useObservedProperty(internalApi.events, 'changeDialog', () => internalApi.dialog);
    const spinner = useObservedProperty(internalApi.events, 'changeSpinner', () => internalApi.spinner);

    return (
        <>
            <div ref={ref}
                style={{
                    display: 'none',
                    // Use non-custom property to resolve `calc()` and different CSS units
                    maxWidth: 'var(--reactodia-dialog-viewport-breakpoint-s)',
                }}
            />
            {dialog}
            {spinner}
        </>
    );
}

function LoadingWidget(props: { spinnerProps: SpinnerProps }) {
    const {spinnerProps} = props;
    const size = useViewportSize();
    const position: Vector = {
        x: spinnerProps.statusText ? size.width / 3 : size.width / 2,
        y: size.height / 2,
    };
    return (
        <ViewportOverlay className='reactodia-loading-widget'>
            <svg width={size.width} height={size.height}>
                <Spinner position={position} {...spinnerProps} />
            </svg>
        </ViewportOverlay>
    );
}

function ViewportDialog(props: DialogProps) {
    const viewportSize = useViewportSize();

    const overlayRef = React.useRef<HTMLDivElement>(null);
    const [margin, setMargin] = React.useState(0);
    React.useLayoutEffect(() => {
        if (overlayRef.current) {
            setMargin(getParentDockMargin(overlayRef.current) ?? 0);
        }
    }, []);

    const maxSize = React.useMemo(
        (): Size => ({
            width: viewportSize.width - margin * 2,
            height: viewportSize.height - margin * 2,
        }),
        [viewportSize, margin]
    );
    return (
        <ViewportOverlay innerRef={overlayRef}
            className='reactodia-viewport-dialog-overlay'>
            <Dialog {...props}
                dock='e'
                maxSize={maxSize}
            />
        </ViewportOverlay>
    );
}

function ViewportOverlay(props: {
    innerRef?: React.RefObject<HTMLDivElement>;
    className?: string;
    children: React.ReactNode;
}) {
    const {innerRef, className, children} = props;
    const {canvas} = useCanvas();
    const renderingState = canvas.renderingState as MutableRenderingState;
    React.useLayoutEffect(() => {
        renderingState.changeInteractionBlocks(1);
        return () => renderingState.changeInteractionBlocks(-1);
    }, [renderingState]);
    return (
        <div ref={innerRef}
            className={cx('reactodia-viewport-overlay', className)}>
            {children}
        </div>
    );
}

function useViewportSize() {
    const {canvas} = useCanvas();
    const resizeStore = useLayerDebouncedStore(
        useEventStore(canvas.events, 'resize'),
        canvas.renderingState
    );
    const size = useSyncStoreWithComparator(
        resizeStore,
        (): Size => {
            const {clientWidth, clientHeight} = canvas.metrics.pane;
            return {width: clientWidth, height: clientHeight};
        },
        (a, b) => a.width === b.width && a.height === b.height
    );
    return size;
}

function getErrorMessage(error: unknown): string | undefined {
    if (error && typeof error === 'object' && 'message' in error) {
        const message = error.message;
        if (typeof message === 'string') {
            return message;
        }
    }
    return undefined;
}

/**
 * Default dialog settings provider which persists changed dialog size in-memory
 * for each {@link OverlayDialog.knownType}.
 *
 * Dialogs without {@link OverlayDialog.knownType} are ignored.
 *
 * @category Core
 */
export class DefaultDialogSettingsProvider implements DialogSettingsProvider {
    private lastDialogSize = new Map<OverlayDialogType, Size>();

    getDialogSize(
        dialog: OverlayDialog
    ): Pick<DialogStyleProps, 'defaultSize' | 'minSize' | 'maxSize'> | undefined {
        if (dialog.knownType) {
            const lastSize = this.lastDialogSize.get(dialog.knownType);
            if (lastSize) {
                return {defaultSize: lastSize};
            }
        }
        return undefined;
    }

    persistDialogSize(dialog: OverlayDialog, size: Size): void {
        if (dialog.knownType) {
            this.lastDialogSize.set(dialog.knownType, size);
        }
    }
}
